        ctx.lines_as(
            "Shalima",
            args!["Oh...?", "what is that shining object you're carrying with you? Isn't that...?"],
        )?;
        ctx.next()?;
        ctx.lines_as("Shalima", args!["The ^3355FFStamp of Muriniel^000000? What a surprise!"])?;
        ctx.next()?;
        ctx.lines_as("Shalima", args!["When you go East from the entrance of Juno, you will find the Street of Book Stores. If you have some time, please visit ^3355FFSir Yklah^000000 who is one of 3 well-known sages in Juno."])?;
